<script setup lang="ts">
import { ApiOutlined, CheckCircleOutlined, SaveOutlined, SafetyCertificateOutlined, CodeOutlined, LoadingOutlined } from '@ant-design/icons-vue'
import type { PublicSettings, SystemStatus } from '../../shared/types'
const {data:config}=await useFetch<PublicSettings>('/api/settings')
const {data:system}=await useFetch<SystemStatus>('/api/system')
const form=reactive({baseUrl:config.value?.baseUrl||'',apiKey:'',model:config.value?.model||'',temperature:config.value?.temperature??0.2,maxTokens:config.value?.maxTokens||12000,delayedBranching:false,clearKey:false,reasoningMode:config.value?.reasoningMode||'auto',reasoningEffort:config.value?.reasoningEffort||'high',autoRepair:config.value?.autoRepair??true})
const thinkingActive=computed(()=>form.reasoningMode==='deepseek'||form.reasoningMode==='openai'||(form.reasoningMode==='auto'&&/deepseek|^(?:o[134](?:-|$)|gpt-[56](?:[.-]|$))/i.test(form.model)))
const saving=ref(false),testing=ref(false),notice=ref(''),error=ref(''),hasKey=ref(!!config.value?.hasKey)
async function save(){saving.value=true;error.value='';notice.value='';try{const r=await $fetch<PublicSettings>('/api/settings',{method:'PUT',body:form});hasKey.value=r.hasKey;form.apiKey='';form.clearKey=false;notice.value='设置已保存。';return true}catch(e:any){error.value=e.data?.statusMessage||e.message;return false}finally{saving.value=false}}
async function test(){testing.value=true;try{if(!await save())return;notice.value='';const r=await $fetch<{ok:boolean;duration:number}>('/api/settings/test',{method:'POST',body:{}});notice.value=`连接成功，响应耗时 ${(r.duration/1000).toFixed(1)} 秒。`}catch(e:any){error.value=e.data?.statusMessage||e.message}finally{testing.value=false}}
</script>
<template><div class="page settings-page"><div class="page-heading"><div><h1>模型与设置<span class="heading-dot">.</span></h1></div></div><div class="settings-layout"><section class="settings-card"><div class="section-heading"><span class="section-icon"><ApiOutlined/></span><div><h2>模型连接</h2><p>用于生成测试数据。</p></div></div><a-alert v-if="error" :message="error" type="error" show-icon/><a-alert v-if="notice" :message="notice" type="success" show-icon/><a-form layout="vertical" :model="form" @finish="save"><a-form-item label="API URL" name="baseUrl" :rules="[{required:true,message:'请输入 API URL'}]"><a-input v-model:value="form.baseUrl" placeholder="http://localhost:11434/v1"/><div class="field-note">支持 Base URL 或完整的 /chat/completions 地址。</div></a-form-item><a-form-item label="API Key"><a-input-password v-model:value="form.apiKey" :placeholder="hasKey?'留空保留已保存密钥':'可留空'" autocomplete="new-password"/><a-checkbox v-if="hasKey" v-model:checked="form.clearKey" class="clear-key">删除已保存的密钥</a-checkbox></a-form-item><a-form-item label="模型名称"><a-input v-model:value="form.model" placeholder="例如 qwen3:14b"/></a-form-item><div class="form-grid"><a-form-item label="思考参数格式"><a-select v-model:value="form.reasoningMode" :options="[{value:'auto',label:'自动识别模型'},{value:'deepseek',label:'DeepSeek 思考模式'},{value:'openai',label:'OpenAI 兼容强度参数'},{value:'off',label:'不发送思考参数'}]"/></a-form-item><a-form-item label="思考强度"><a-select v-model:value="form.reasoningEffort" :disabled="form.reasoningMode==='off'" :options="[{value:'high',label:'high · 高（默认）'},{value:'max',label:'max · 最高'},{value:'medium',label:'medium · 中'},{value:'low',label:'low · 低'},{value:'default',label:'服务默认'}]"/></a-form-item></div><div class="form-grid"><a-form-item label="Temperature"><a-input-number v-model:value="form.temperature" :disabled="thinkingActive" :min="0" :max="2" :step="0.1" style="width:100%"/></a-form-item><a-form-item label="最大输出 Token"><a-input-number v-model:value="form.maxTokens" :min="1000" :max="64000" :step="1000" style="width:100%"/></a-form-item></div><p v-if="thinkingActive" class="field-note">思考模式下 Temperature 不生效。</p><a-form-item><a-checkbox v-model:checked="form.autoRepair">校验失败后自动修复一次</a-checkbox><p class="field-note">启用后每次生成最多调用模型两次。</p></a-form-item><div class="settings-actions"><a-button :loading="testing" @click="test"><template #icon><ApiOutlined/></template>保存并测试连接</a-button><a-button type="primary" html-type="submit" :loading="saving"><template #icon><SaveOutlined/></template>保存设置</a-button></div></a-form></section><aside><section class="rail-card runtime-card"><h3><SafetyCertificateOutlined/>运行环境</h3><div class="runtime-row"><span>MARS 4.5</span><span :class="system?.mars?'runtime-ok':'runtime-bad'">{{system?.mars?'已就绪':'未安装'}}</span></div><div class="runtime-row"><span>执行隔离</span><span :class="system?.sandbox?'runtime-ok':'runtime-bad'">{{system?.sandbox?system.isolation:'不可用'}}</span></div><div class="runtime-row"><span>出站网络</span><span>{{system?.network?.mode}}<template v-if="system?.network?.endpoint"> · {{system.network.endpoint}}</template></span></div><div class="runtime-row"><span>输出比较</span><span>忽略空白差异</span></div><div class="runtime-row"><span>单次输出上限</span><span>1 MiB</span></div></section></aside></div><section class="settings-card judge-settings"><div class="section-heading"><span class="section-icon"><CodeOutlined/></span><div><h2>MIPS 评测规则</h2></div></div><div class="toggle-row"><div><strong>延迟槽</strong></div><a-tag color="green">关闭</a-tag></div><div class="settings-footnote">支持伪指令，禁用 .globl main。syscall 5 每次读取一行整数。</div></section></div></template>
